const I=({children}:{children:React.ReactNode})=><span className="ico">{children}</span>;
function DesignSpecIcon(){return <svg viewBox="2 2 20 20" width="20" height="20" aria-hidden="true"><path d="M16.167 5.333a2.5 2.5 0 1 1 0 5 2.5 2.5 0 0 1 0-5ZM7.833 14a2.5 2.5 0 1 1 0 5 2.5 2.5 0 0 1 0-5ZM13.667 13.667h5v4.166a.833.833 0 0 1-.834.834H14.5a.833.833 0 0 1-.833-.834v-4.166ZM5.333 5.333h5V9.5a.833.833 0 0 1-.833.833H6.167a.833.833 0 0 1-.834-.833V5.333Z" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round"/></svg>}
function WorkspaceArrows(){return <svg className="workspace-arrows" viewBox="0 0 24 24" width="14" height="14" aria-hidden="true"><path d="m7 15 5 5 5-5"/><path d="m7 9 5-5 5 5"/></svg>}
const assets={logo:'https://app.paper.design/file-assets/01KXZGWVDJX4V0T4SRNACBP8J3/01KYVN117ADYQ9VBFR4ZC132KZ.png',waveA:'https://app.paper.design/file-assets/01KXZGWVDJX4V0T4SRNACBP8J3/3BHJEZWHTRB5DC7H3NTRZZ1MDJ.svg',waveB:'https://app.paper.design/file-assets/01KXZGWVDJX4V0T4SRNACBP8J3/7S639QM9CCQXK32A2BY9EY8NVY.svg',leo:'https://app.paper.design/file-assets/01KXZGWVDJX4V0T4SRNACBP8J3/6VA04GD3X43QX46Y6HXSVYRS92.jpg',lily:'https://app.paper.design/file-assets/01KXZGWVDJX4V0T4SRNACBP8J3/2WSXV8KJ7VTBAY9DWYE5827EQX.png',tea:'https://app.paper.design/file-assets/01KXZGWVDJX4V0T4SRNACBP8J3/35XVFKHG8T5FJEVDG7R04T5WYC.jpg',avatar:'https://app.paper.design/file-assets/01KXZGWVDJX4V0T4SRNACBP8J3/45V1SSC6CW6Z53VW1B9VRQ9BR2.jpg',railAvatar:'https://app.paper.design/file-assets/01KXZGWVDJX4V0T4SRNACBP8J3/3PQ50478K53G7QW0A81EN0V95Q.png'};
const nav=[['首页',<HomeIcon/>],['项目',<FolderKanban/>],['资产库',<Compass/>]];
