type AppPage='home'|'project'|'projects'|'assets'|'specs'|'skills'|'connectors'|'team';

function Logo(){return <div className="logo"><img src={assets.logo}/><b>Imagine Lab</b></div>}
function Avatar({rail=false}:{rail?:boolean}){return <span className="avatar" style={{backgroundImage:`url(${rail?assets.railAvatar:assets.avatar})`}}/>}
function TeamPill(){return <div className="team-pill"><b>想象力产品部</b><Avatar/></div>}
function BrandMotto(){return <div className="brand-motto" aria-label="Imagine Lab 品牌宣言"><p>让想象力，<br/>成为团队的生产力。</p><span className="brand-motto-mark"><img src={assets.logo} alt="Imagine Lab"/><b>Imagine Lab</b></span></div>}

function ApiSettingsModal({onClose}:{onClose:()=>void}){const [provider,setProvider]=useState('OpenAI');const [saved,setSaved]=useState(false);const [testing,setTesting]=useState(false);const providers=[['OpenAI','GPT-5.6','页面生成与复杂修改'],['Anthropic','Claude Sonnet','长文档与前端理解'],['DeepSeek','DeepSeek V3','轻量文本整理与需求总结']];return <div className="api-settings-layer" onPointerDown={event=>{if(event.target===event.currentTarget)onClose()}}><section className="api-settings-modal"><header><div><small>个人模型服务</small><h2>API 设置</h2><p>密钥只保存在本机；调用时优先使用你选择的模型。</p></div><button onClick={onClose}><X/></button></header><div className="api-provider-list">{providers.map(([name,model,detail])=><button className={provider===name?'selected':''} onClick={()=>{setProvider(name);setSaved(false)}} key={name}><span>{name.slice(0,1)}</span><div><b>{name}</b><small>{detail}</small></div><em>{model}</em>{provider===name&&<CircleCheck/>}</button>)}</div><div className="api-key-form"><label><span>{provider} API Key</span><input type="password" defaultValue="sk-imagine-lab-demo-key"/></label><label><span>默认模型</span><select defaultValue={providers.find(item=>item[0]===provider)?.[1]}>{providers.filter(item=>item[0]===provider).map(item=><option key={item[1]}>{item[1]}</option>)}</select></label><div className="api-privacy"><ShieldCheck/><span><b>仅在本机加密保存</b><small>项目成员不会看到你的密钥，团队请求也不会自动消耗你的额度。</small></span></div></div><footer><button className="api-test" onClick={()=>{setTesting(true);window.setTimeout(()=>setTesting(false),900)}}>{testing?<LoaderCircle/>:<Zap/>}{testing?'正在测试':'测试连接'}</button><button className="api-save" onClick={()=>setSaved(true)}>{saved?<Check/>:null}{saved?'已保存':'保存设置'}</button></footer></section></div>}
function HomeSidebar({goProject,goHome,collapsed,active='home',onNavigate}:{goProject:()=>void,goHome?:()=>void,collapsed:boolean,active?:AppPage,onNavigate?:(page:AppPage)=>void}){const [apiOpen,setApiOpen]=useState(false);const go=(page:AppPage)=>{if(page==='home')goHome?.();else if(page==='project')goProject();else onNavigate?.(page)};const productPages:AppPage[]=['specs','team'];return <><aside className={'home-side '+(collapsed?'collapsed':'')}><Logo/><button className="workspace" title="UI设计"><WandSparkles/><span className="workspace-name">UI设计</span><WorkspaceArrows/></button><div className="nav-block">{nav.map(([n,icon],i)=>{const page:AppPage=i===0?'home':i===1?'projects':'assets';return <button key={n as string} title={n as string} className={active===page||(i===1&&active==='project')?'active':''} onClick={()=>go(page)}><I>{icon}</I><span className="nav-name">{n}</span></button>})}</div><div className="nav-block">{products.map(([n,icon],index)=>{const isActive=index===0?(['specs','skills','connectors'] as AppPage[]).includes(active):active==='team';return <button key={n as string} title={n as string} className={isActive?'active':''} onClick={()=>go(productPages[index])}><I>{icon}</I><span className="nav-name">{n}</span></button>})}</div><BrandMotto/><button className="quota" title="API 设置" onClick={()=>setApiOpen(true)}><span className="api-top"><KeyRound/><b>API 设置</b><small>68%</small><ChevronRight/></span><span className="api-progress"><i/></span></button></aside>{apiOpen&&<ApiSettingsModal onClose={()=>setApiOpen(false)}/>}</>}

const quick=[
  [<WandSparkles/>,'延展页面','进入已有项目，基于页面、规范与组件，由 AI 新增或修改页面'],
  [<Import/>,'导入项目','导入完整设计项目或代码仓库，建立项目模型'],
  [<Boxes/>,'导入资产','向现有项目补充组件、规范与资源文件']
];
type QuickFlow='extend'|'project-import'|'asset-import';
const quickFlows:QuickFlow[]=['extend','project-import','asset-import'];
const projects=[['想象力智能中高考','Leo','今天编辑于 10:52'],['速学慧','Lily & Leo','编辑于 7/29 12:27'],['代理商小程序','雅木茶','编辑于 7/24 10:12']];
function Header({crumb='首页',online=false,onToggleSidebar}:{crumb?:string,online?:boolean,onToggleSidebar?:()=>void}){const parts=crumb.split(' / ');return <header className="top"><button className="crumb" onClick={onToggleSidebar}><PanelLeft/><span className="crumb-label">{parts.map((part,i)=><React.Fragment key={part}><b className={i===0&&parts.length>1?'muted-crumb':''}>{part}</b>{i<parts.length-1&&<span className="crumb-separator">/</span>}</React.Fragment>)}</span></button><div className="top-actions">{online&&<span className="online"><i/>1 人在线</span>}<button className="circle"><MessageCircle/></button><TeamPill/></div></header>}
type AnalysisMethod='local'|'connector'|'browser';
type AnalysisSource=[string,string,string];
const analysisMethods:{id:AnalysisMethod;title:string;description:string;icon:React.ReactNode;sources:AnalysisSource[]}[]=[
  {id:'local',title:'直接读取本地资料',description:'选择资料后，AI 将自动读取其中的 Markdown 与文本内容',icon:<FolderOpen/>,sources:[['obsidian','Obsidian','/source-logos/obsidian.svg']]},
  {id:'connector',title:'连接在线文档',description:'授权后自动查找并读取相关产品文档，无需手动导出',icon:<Link2/>,sources:[['feishu','飞书','/source-logos/feishu.ico'],['notion','Notion','/source-logos/notion.ico']]},
  {id:'browser',title:'浏览器辅助读取',description:'调用浏览器访问受限平台，仅提取文档中的产品文本',icon:<MonitorUp/>,sources:[['lanhu','蓝湖','/source-logos/lanhu.ico'],['modao','墨刀','/source-logos/modao.ico']]}
];
const analysisSteps:Record<AnalysisMethod,string[]>={
  local:['正在连接本地资料','正在读取 Markdown 与文本文件','正在过滤界面、交互与代码信息','正在提炼产品问题与解决方案'],
  connector:['正在连接文档服务','正在定位相关产品资料','正在读取正文与关联文档','正在提炼产品问题与解决方案'],
  browser:['正在调用浏览器辅助读取','正在定位项目中的产品文档','正在提取文本，跳过 UI、交互与代码','正在提炼产品问题与解决方案']
};
function SourceList({sources}:{sources:AnalysisSource[]}){return <span className="source-list">{sources.map(([type,name,logo])=><React.Fragment key={type}><i className={'source-mark '+type}><img src={logo} alt=""/></i><em>{name}</em></React.Fragment>)}</span>}
function PrototypeAnalysisModal({onClose}:{onClose:()=>void}){const [method,setMethod]=useState<AnalysisMethod|null>(null);const [pendingMethod,setPendingMethod]=useState<AnalysisMethod|null>(null);const [picker,setPicker]=useState<AnalysisMethod|null>(null);const [source,setSource]=useState<AnalysisSource|null>(null);const [step,setStep]=useState(0);useEffect(()=>{const close=(event:KeyboardEvent)=>{if(event.key==='Escape')onClose()};document.addEventListener('keydown',close);return()=>document.removeEventListener('keydown',close)},[onClose]);useEffect(()=>{if(!method)return;setStep(0);const timer=window.setInterval(()=>setStep(value=>{if(value>=analysisSteps[method].length-1){window.clearInterval(timer);return value}return value+1}),1150);return()=>window.clearInterval(timer)},[method]);const selected=method?analysisMethods.find(item=>item.id===method):null;const pickerData=picker?analysisMethods.find(item=>item.id===picker):null;const continueMethod=()=>{if(!pendingMethod)return;if(pendingMethod==='connector'){setPicker(pendingMethod);setPendingMethod(null);return}setSource(null);setMethod(pendingMethod);setPendingMethod(null)};const goBack=()=>{if(method){setMethod(null);setSource(null);return}setPicker(null)};const title=method?'正在分析产品原型':picker?'连接在线文档':'原型分析';const subtitle=method?'AI 只会读取产品内容，自动忽略 UI、交互与代码':picker?'选择需要连接的文档产品':'选择资料的读取方式，后续步骤将自动完成';return <div className="analysis-modal-backdrop" onPointerDown={event=>{if(event.target===event.currentTarget)onClose()}}><section className={'analysis-modal '+(method?'is-processing':'')} role="dialog" aria-modal="true" aria-labelledby="analysis-modal-title"><div className="analysis-modal-head"><div>{(method||picker)&&<button className="analysis-back" onClick={goBack}><ArrowLeft/>{method?'重新选择':'返回'}</button>}<h2 id="analysis-modal-title">{title}</h2><p>{subtitle}</p></div><button className="analysis-modal-close" aria-label="关闭" onClick={onClose}><X/></button></div>{!method&&!picker?<><div className="analysis-options">{analysisMethods.map(item=>{const isSelected=pendingMethod===item.id;return <button className={'analysis-option '+(isSelected?'selected':'')} aria-pressed={isSelected} key={item.id} onClick={()=>setPendingMethod(item.id)}><span className={'analysis-option-icon '+item.id}>{item.icon}</span><span className="analysis-option-copy"><b>{item.title}</b><small>{item.description}</small><SourceList sources={item.sources}/></span>{isSelected?<span className="analysis-selected-mark"><Check/></span>:null}</button>})}</div><button className="analysis-continue" disabled={!pendingMethod} onClick={continueMethod}>继续<ArrowUp/></button></>:!method&&pickerData?<div className="analysis-provider-list">{pickerData.sources.map(item=><button className="analysis-provider" key={item[0]} onClick={()=>{setSource(item);setMethod(picker)}}><span className={'provider-logo '+item[0]}><img src={item[2]} alt=""/></span><span><b>{item[1]}</b><small>授权并连接 {item[1]} 文档</small></span><ChevronRight/></button>)}</div>:method?<div className="analysis-progress"><div className="analysis-agent"><span className="analysis-agent-mark"><WandSparkles/></span><div><b>Imagine AI</b><small>{selected?.title}</small></div><SourceList sources={source?[source]:selected?.sources??[]}/></div><div className="analysis-thinking"><div className="thinking-title"><LoaderCircle className="thinking-spinner"/><b>正在思考</b><span><i/><i/><i/></span></div><p>{analysisSteps[method][step]}</p></div><div className="analysis-step-list">{analysisSteps[method].map((label,index)=><div className={'analysis-step '+(index<step?'done':index===step?'active':'')} key={label}>{index<step?<CircleCheck/>:<span/>}<p>{label}</p>{index===step&&<small>进行中</small>}</div>)}</div><div className="analysis-reading-rule"><b>读取规则</b><p>仅保留产品定位、用户问题、目标用户、业务逻辑与解决方案；跳过视觉样式、交互标注、组件参数和代码内容。</p></div></div>:null}</section></div>}
function QuickEntryModal({flow,onClose,onEnter}:{flow:QuickFlow;onClose:()=>void;onEnter:()=>void}){
  const [step,setStep]=useState(0);const [selected,setSelected]=useState('速学慧');const [source,setSource]=useState(flow==='project-import'?'design':'component');const [terminal,setTerminal]=useState('H5');const [progress,setProgress]=useState(0);
  useEffect(()=>{const close=(event:KeyboardEvent)=>{if(event.key==='Escape')onClose()};document.addEventListener('keydown',close);return()=>document.removeEventListener('keydown',close)},[onClose]);
  useEffect(()=>{if(step!==2)return;const timer=window.setInterval(()=>setProgress(value=>{if(value>=3){window.clearInterval(timer);return value}return value+1}),900);return()=>window.clearInterval(timer)},[step]);
  const meta={extend:['延展页面','选择一个已有项目，AI 将继承它的页面结构、设计规范与代码组件。'],'project-import':['导入项目','把完整设计项目或代码仓库转换为可维护的代码页面与组件。'],'asset-import':['导入资产','向已有项目补充代码组件、设计规范或资源文件。']}[flow];
  const action=flow==='extend'?'进入项目画布':flow==='project-import'?'开始导入':'导入到项目';
  const next=()=>{if(flow==='project-import'&&step===1){setStep(2);return}if(step===0){setStep(1);return}onEnter()};
  const importSteps=['正在建立受控读取范围','正在识别页面结构与组件关系','正在转换并验证前端 UI 代码','正在整理待确认规范与组件'];
  return <div className="quick-entry-layer" onPointerDown={event=>{if(event.target===event.currentTarget)onClose()}}><section className="quick-entry-modal" role="dialog" aria-modal="true"><header><div>{step>0&&step<2?<button className="quick-entry-back" onClick={()=>setStep(step-1)}><ArrowLeft/>返回</button>:null}<h2>{step===2?'正在导入项目':meta[0]}</h2><p>{step===2?'系统会按节约读取规则完成转换，过程中不会修改源项目。':meta[1]}</p></div><button className="quick-entry-close" onClick={onClose}><X/></button></header>
    {step===0&&flow!=='project-import'&&<div className="quick-entry-projects"><span className="quick-entry-label">选择项目</span>{projects.map((project,index)=><button className={selected===project[0]?'selected':''} onClick={()=>setSelected(project[0])} key={project[0]}><span className={'quick-project-mark p'+index}><FolderKanban/></span><span><b>{project[0]}</b><small>{index===1?'核心规范已锁定 · 34 个可用组件':index===0?'团队规范 · 28 个可用组件':'项目规范 · 19 个可用组件'}</small></span>{selected===project[0]?<CircleCheck/>:<ChevronRight/>}</button>)}</div>}
    {step===0&&flow==='project-import'&&<div className="quick-entry-sources"><span className="quick-entry-label">选择项目来源</span><button className={source==='design'?'selected':''} onClick={()=>setSource('design')}><span><LayoutTemplate/></span><b>设计项目</b><small>Figma、Sketch 等完整设计文件</small>{source==='design'&&<CircleCheck/>}</button><button className={source==='code'?'selected':''} onClick={()=>setSource('code')}><span><Code2/></span><b>代码仓库</b><small>GitHub、GitLab 或本地项目</small>{source==='code'&&<CircleCheck/>}</button><div className="quick-entry-skill-note"><Sparkles/><span><b>专业导入助手</b><small>先扫描目录与页面入口，再按需读取，减少无关内容与模型消耗。</small></span></div></div>}
    {step===1&&flow==='extend'&&<div className="quick-entry-setup"><div className="quick-selected-project"><FolderKanban/><span><small>当前项目</small><b>{selected}</b></span><em>页面、规范与组件已就绪</em></div><label>想新增或修改什么页面？<textarea autoFocus placeholder="例如：为课程详情延展一个分享页面，沿用现有结构与品牌规范。"/></label><p className="quick-entry-hint"><Sparkles/>进入画布后，可直接描述需求，也可以选择组件作为代码参考并指定目标区域。</p></div>}
    {step===1&&flow==='project-import'&&<div className="quick-entry-setup"><div className="quick-selected-project">{source==='design'?<LayoutTemplate/>:<Code2/>}<span><small>导入来源</small><b>{source==='design'?'完整设计项目':'代码仓库'}</b></span><button>选择文件或连接来源</button></div><span className="quick-entry-label">生成目标</span><div className="quick-terminal-list">{['Web','App','H5'].map(item=><button className={terminal===item?'selected':''} onClick={()=>setTerminal(item)} key={item}><MonitorUp/><b>{item}</b>{terminal===item&&<Check/>}</button>)}</div><div className="quick-tech-row"><Code2/><span><small>技术规范</small><b>{terminal==='App'?'React Native · TypeScript':'React · TypeScript'}</b></span><em>AI 推荐</em></div></div>}
    {step===1&&flow==='asset-import'&&<div className="quick-entry-setup"><div className="quick-selected-project"><FolderKanban/><span><small>导入到</small><b>{selected}</b></span><em>不会覆盖现有资产</em></div><span className="quick-entry-label">选择资产类型</span><div className="quick-asset-types">{[['component',<Component/>,'代码组件','可视化组件及其前端代码'],['spec',<SlidersHorizontal/>,'设计规范','颜色、字体、间距和组件规则'],['resource',<Boxes/>,'资源文件','图标、插图和界面素材']].map(([id,icon,title,desc])=><button className={source===id?'selected':''} onClick={()=>setSource(id as string)} key={id as string}>{icon}<span><b>{title}</b><small>{desc}</small></span>{source===id&&<CircleCheck/>}</button>)}</div><button className="quick-file-drop"><Import/><span><b>选择文件或拖入此处</b><small>导入后先进入待确认区，不会直接进入核心资产库。</small></span></button></div>}
    {step===2&&<div className="quick-import-progress"><div className="quick-import-agent"><span><Sparkles/></span><div><b>项目导入助手</b><small>{source==='design'?'设计结构读取模式':'代码入口读取模式'} · {terminal}</small></div><LoaderCircle/></div>{importSteps.map((item,index)=><div className={'quick-import-step '+(index<progress?'done':index===progress?'active':'')} key={item}>{index<progress?<CircleCheck/>:<span/>}<b>{item}</b>{index===progress&&<small>进行中</small>}</div>)}<div className="quick-import-rule"><SlidersHorizontal/><span><b>读取边界已启用</b><small>跳过依赖包、历史记录和无关业务代码，只读取 UI 结构、样式、组件及页面入口。</small></span></div></div>}
    {step<2&&<footer><button className="quick-entry-secondary" onClick={onClose}>取消</button><button className="quick-entry-primary" onClick={next}>{step===0?'继续':action}<ArrowUp/></button></footer>}{step===2&&progress>=3&&<footer><button className="quick-entry-primary" onClick={onEnter}>进入项目画布<ArrowUp/></button></footer>}
  </section></div>
}
