function ProjectList(){
  const [menu,setMenu]=useState<number|null>(null);const [collapsed,setCollapsed]=useState(false);const [items,setItems]=useState(['想象力智能中高考','速学慧客户端','代理商小程序','速学慧H5']);const [editing,setEditing]=useState<{index:number;value:string}|null>(null);const [dragging,setDragging]=useState<string|null>(null);const [dragOffset,setDragOffset]=useState(0);const drag=React.useRef<{name:string;startIndex:number;startY:number}|null>(null);const selected='速学慧H5';
  useEffect(()=>{if(menu===null)return;const closeMenu=(event:PointerEvent)=>{const target=event.target as Element|null;if(target?.closest('.context-menu, .project-more'))return;setMenu(null)};document.addEventListener('pointerdown',closeMenu);return()=>document.removeEventListener('pointerdown',closeMenu)},[menu]);
  useEffect(()=>{if(!dragging)return;const move=(event:PointerEvent)=>{const active=drag.current;if(!active)return;const distance=event.clientY-active.startY;const target=Math.max(0,Math.min(items.length-1,active.startIndex+Math.round(distance/48)));setItems(current=>{const currentIndex=current.indexOf(active.name);setDragOffset(distance-(currentIndex-active.startIndex)*48);if(currentIndex===target)return current;const reordered=[...current];reordered.splice(currentIndex,1);reordered.splice(target,0,active.name);setDragOffset(distance-(target-active.startIndex)*48);return reordered})};const end=()=>{setDragging(null);setDragOffset(0);drag.current=null};document.addEventListener('pointermove',move);document.addEventListener('pointerup',end,{once:true});return()=>{document.removeEventListener('pointermove',move);document.removeEventListener('pointerup',end)}},[dragging,items.length]);
  const beginDrag=(event:React.PointerEvent,name:string,index:number)=>{if(event.button!==0)return;event.preventDefault();event.stopPropagation();setMenu(null);setDragging(name);drag.current={name,startIndex:index,startY:event.clientY}};
  const commitRename=()=>{if(!editing)return;setItems(current=>current.map((item,index)=>index===editing.index?(editing.value.trim()||'空白项目'):item));setEditing(null)};
  const createProject=()=>{const base='空白项目';const name=items.includes(base)?`${base} ${items.filter(item=>item.startsWith(base)).length+1}`:base;const index=items.length;setItems(current=>[...current,name]);setEditing({index,value:name});setMenu(null)};
  return <aside className={'project-list '+(collapsed?'is-collapsed':'')}>{!collapsed&&<>{items.map((x,i)=><div className={'project-item '+(x===selected?'selected ':'')+(dragging===x?'dragging':'')} style={dragging===x?{transform:`translateY(${dragOffset}px)`}:undefined} key={`${x}-${i}`}><div className="project-name"><span className="project-grip" aria-label={`拖动${x}调整顺序`} onPointerDown={event=>{if(editing?.index!==i)beginDrag(event,x,i)}}/>{editing?.index===i?<input autoFocus value={editing.value} onFocus={event=>event.currentTarget.select()} onPointerDown={event=>event.stopPropagation()} onChange={event=>setEditing({...editing,value:event.target.value})} onBlur={commitRename} onKeyDown={event=>{if(event.key==='Enter')event.currentTarget.blur();if(event.key==='Escape'){setEditing(null)}}}/>:<span>{x}</span>}</div><button className="project-more" aria-label={`${x}更多操作`} onClick={()=>setMenu(menu===i?null:i)}><MoreHorizontal/></button></div>)}<button className="create" onClick={createProject}><Plus/>创建空白项目</button></>}<button className="collapse" aria-label={collapsed?'展开项目列表':'收起项目列表'} onClick={()=>{setCollapsed(v=>!v);setMenu(null)}}>{collapsed?'›':'‹'}</button>{menu!==null&&!collapsed&&<div className="context-menu" style={{top:12+(menu+1)*48+4}}><button onClick={()=>{setEditing({index:menu,value:items[menu]});setMenu(null)}}><Pencil/>重命名</button><button className="danger" onClick={()=>{setItems(current=>current.filter((_,index)=>index!==menu));setMenu(null)}}><Trash2/>删除</button></div>}</aside>}

type StructurePage={id:string;name:string;parent?:string};
function PageStructurePanel({onLocate=(name)=>window.dispatchEvent(new CustomEvent('imagine-locate-page',{detail:name}))}:{onLocate?:(name:string)=>void}){
  const [collapsed,setCollapsed]=useState(false);const [active,setActive]=useState('home');const [expanded,setExpanded]=useState<Set<string>>(()=>new Set(['home','plan']));const [editing,setEditing]=useState<string|null>(null);const [draft,setDraft]=useState('未命名页面');const [feedback,setFeedback]=useState('');
  const [pages,setPages]=useState<StructurePage[]>([{id:'home',name:'学习首页'},{id:'today',name:'今日计划',parent:'home'},{id:'plan',name:'课程详情',parent:'home'},{id:'chapter',name:'章节详情',parent:'plan'},{id:'record',name:'成长记录',parent:'home'},{id:'profile',name:'个人中心'},{id:'account',name:'账号资料',parent:'profile'}]);
  const children=(id:string)=>pages.filter(page=>page.parent===id);const descendants=(id:string):string[]=>children(id).flatMap(page=>[page.id,...descendants(page.id)]);const activeDescendants=new Set(descendants(active));
  const toggle=(event:React.MouseEvent,id:string)=>{event.stopPropagation();setExpanded(current=>{const next=new Set(current);next.has(id)?next.delete(id):next.add(id);return next})};
  const commit=()=>{if(!editing)return;setPages(current=>current.map(page=>page.id===editing?{...page,name:draft.trim()||'未命名页面'}:page));setEditing(null);setFeedback('页面已加入结构');window.setTimeout(()=>setFeedback(''),1800)};
  const addPage=()=>{const parent=pages.find(page=>page.id===active);setFeedback('请在预览中选择新页面的跳转入口');window.dispatchEvent(new CustomEvent('imagine-add-page-request',{detail:{parentId:active,parentName:parent?.name||'当前页面'}}));window.setTimeout(()=>setFeedback(''),2600)};
  const select=(page:StructurePage)=>{setActive(page.id);onLocate(page.name);window.dispatchEvent(new CustomEvent('imagine-route-page',{detail:{id:page.id,name:page.name}}))};
  const render=(parent?:string,depth=0):React.ReactNode=>pages.filter(page=>page.parent===parent).map(page=>{const hasChildren=children(page.id).length>0;const open=expanded.has(page.id);const selected=active===page.id;const inherited=activeDescendants.has(page.id);return <React.Fragment key={page.id}><button className={'structure-item '+(depth===0?'root ':'child ')+(selected?'selected ':'')+(inherited?'selected-descendant ':'')} style={{'--tree-depth':depth} as React.CSSProperties} onClick={()=>select(page)}><span className={'tree-toggle '+(!hasChildren?'is-empty':'')} onClick={event=>hasChildren&&toggle(event,page.id)}>{hasChildren?(open?<ChevronDown/>:<ChevronRight/>):null}</span><FileText/>{editing===page.id?<input autoFocus value={draft} onFocus={event=>event.currentTarget.select()} onChange={event=>setDraft(event.target.value)} onBlur={commit} onKeyDown={event=>{if(event.key==='Enter')event.currentTarget.blur();if(event.key==='Escape')setEditing(null)}}/>:<b>{page.name}</b>}<em onClick={event=>{event.stopPropagation();onLocate(page.name)}}>定位</em></button>{hasChildren&&open&&render(page.id,depth+1)}</React.Fragment>});
  return collapsed?<button className="structure-open-button" onClick={()=>setCollapsed(false)}><PanelLeft/>展开结构</button>:<aside className="project-list page-structure"><header className="structure-panel-head"><b>项目结构</b><button aria-label="收起项目结构" onClick={()=>setCollapsed(true)}><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 4v16M19 12H8M12 8l-4 4 4 4"/></svg></button></header><div className="structure-tree">{render()}</div><button className="structure-add" onClick={addPage}><Plus/>添加页面</button>{feedback&&<div className="structure-feedback"><CircleCheck/>{feedback}</div>}</aside>
}
