function Composer({quotedComments,modifications:providedModifications,onClearQuote,onClearModification}:{quotedComments:string[];modifications?:ModificationBatch[];onClearQuote:(index:number)=>void;onClearModification?:(id:number)=>void}){
  const rootRef=useRef<HTMLDivElement>(null);const fileRef=useRef<HTMLInputElement>(null);const [expanded,setExpanded]=useState(false);const [annotationsOpen,setAnnotationsOpen]=useState(false);const [prompt,setPrompt]=useState('');const [attachmentCount,setAttachmentCount]=useState(0);const [localModifications,setLocalModifications]=useState<ModificationBatch[]>([]);const modifications=providedModifications??localModifications;const annotationCount=quotedComments.length+modifications.reduce((total,batch)=>total+batch.items.length,0);const hasReferences=annotationCount>0;
  useEffect(()=>{const receive=(event:Event)=>setLocalModifications(current=>[...current,(event as CustomEvent<ModificationBatch>).detail]);window.addEventListener('imagine-modifications',receive);return()=>window.removeEventListener('imagine-modifications',receive)},[]);
  useEffect(()=>{if(!expanded)return;const collapse=(event:PointerEvent)=>{if(!prompt.trim()&&!rootRef.current?.contains(event.target as Node)){setExpanded(false);setAnnotationsOpen(false)}};document.addEventListener('pointerdown',collapse,true);return()=>document.removeEventListener('pointerdown',collapse,true)},[expanded,prompt]);
  useEffect(()=>{if(!expanded)return;const stage=rootRef.current?.closest('.stage') as HTMLElement|null;if(!stage)return;const fit=()=>{const stageRect=stage.getBoundingClientRect();const leftPanel=stage.querySelector('.page-structure') as HTMLElement|null;const rightPanel=stage.querySelector('.workspace-panel') as HTMLElement|null;const leftEdge=leftPanel?.getBoundingClientRect().right??stageRect.left;const rightEdge=rightPanel?.getBoundingClientRect().left??stageRect.right;if(rightEdge-leftEdge<=528){setExpanded(false);setAnnotationsOpen(false)}};fit();const resize=new ResizeObserver(fit);resize.observe(stage);const mutation=new MutationObserver(fit);mutation.observe(stage,{childList:true,subtree:false});window.addEventListener('resize',fit);return()=>{resize.disconnect();mutation.disconnect();window.removeEventListener('resize',fit)}},[expanded]);
  const clearModification=(id:number)=>onClearModification?onClearModification(id):setLocalModifications(current=>current.filter(item=>item.id!==id));
  const send=()=>{if(!prompt.trim()&&!hasReferences&&!attachmentCount)return;setPrompt('');setAttachmentCount(0);setAnnotationsOpen(false)};
  return <div ref={rootRef} className={'composer paper-chat-composer '+(expanded?'is-expanded ':'is-collapsed ')+(hasReferences?'has-quote':'')} onClick={()=>setExpanded(true)}>
    {expanded&&hasReferences&&<div className="composer-annotation-bar"><button onClick={event=>{event.stopPropagation();setAnnotationsOpen(value=>!value)}} aria-expanded={annotationsOpen}><PaperAnnotationIcon/><span>{annotationCount}条注释</span></button></div>}
    {annotationsOpen&&<div className="composer-annotation-popover" onClick={event=>event.stopPropagation()}>{modifications.flatMap(batch=>batch.items.map((item,index)=><div key={`${batch.id}-${index}`}><Component/><span><small>{batch.title}</small><b>{item.text}</b></span><button onClick={()=>clearModification(batch.id)} aria-label="移除注释"><X/></button></div>))}{quotedComments.map((comment,index)=><div key={`${comment}-${index}`}><MessageCircle/><span><small>评论引用</small><b>{comment}</b></span><button onClick={()=>onClearQuote(index)} aria-label="移除注释"><X/></button></div>)}</div>}
    <div className="composer-input-region">{!expanded&&<img className="composer-collapsed-logo" src={assets.logo} alt=""/>}<textarea value={prompt} onFocus={()=>setExpanded(true)} onChange={event=>setPrompt(event.target.value)} onKeyDown={event=>{if(event.key==='Enter'&&!event.shiftKey){event.preventDefault();send()}}} placeholder="描述你的设计需求…" rows={1}/></div>
    {expanded&&<div className="composer-actions"><input ref={fileRef} type="file" multiple hidden onChange={event=>setAttachmentCount(event.currentTarget.files?.length||0)}/><button className="composer-add-material" onClick={event=>{event.stopPropagation();fileRef.current?.click()}}><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 7v14M13.172 4.172A4 4 0 0 0 12 7a4 4 0 0 0-4-4H3a1 1 0 0 0-1 1v13a1 1 0 0 0 1 1h6a3 3 0 0 1 3 3 3 3 0 0 1 3-3h6a1 1 0 0 0 1-1v-7"/><path className="material-spark" d="M18 3 19.053.894a.5.5 0 0 1 .894 0L21 3l2.106 1.053a.5.5 0 0 1 0 .894L21 6l-1.053 2.106a.5.5 0 0 1-.894 0L18 6l-2.106-1.053a.5.5 0 0 1 0-.894z"/></svg>{attachmentCount?`${attachmentCount}项资料`:'添加资料'}</button><button className="send" aria-label="发送" onClick={event=>{event.stopPropagation();send()}}><ArrowUp/></button></div>}
  </div>
}
const defaultProjectContext=`# 角色\n你是一个产品需求全流程协同助手，服务于产品团队从需求规划、产品理解、UI 设计到前端交付的完整周期。\n\n# 项目目标\n为速学慧建立清晰、连续且可复用的学习成长体验，帮助学生理解今日任务、持续完成学习计划，并看见自己的阶段性进步。\n\n# 核心用户\n中学生、家长与教学服务团队。\n\n# 工作原则\n- 优先解决真实的学习问题，不以视觉表现替代产品逻辑。\n- 生成页面时遵循当前设计规范、组件资产与技术约束。\n- 每次修改保留可追溯的设计决策，并优先复用已有组件。`;
function ProjectExportModal({onClose}:{onClose:()=>void}){const [choice,setChoice]=useState('delivery');const options=[['delivery',<Download/>,'前端交付包','全部已确认页面、组件、规范快照、资源与运行说明'],['document',<FileText/>,'项目说明文档','页面结构、交互状态、业务说明与变更摘要'],['archive',<Archive/>,'项目归档备份','项目配置、页面版本与资产关系，用于迁移或恢复']];return <div className="canvas-flow-layer" onPointerDown={event=>{if(event.target===event.currentTarget)onClose()}}><section className="canvas-flow-modal project-export-modal"><header><div><small>速学慧 H5</small><h2>导出项目</h2><p>导出整个项目已经确认的成果；单张页面请从画布“更多”中导出。</p></div><button onClick={onClose}><X/></button></header><div className="canvas-flow-body"><div className="export-options">{options.map(([id,icon,title,detail])=><label className={choice===id?'selected':''} key={id as string}><input type="radio" name="project-export" checked={choice===id} onChange={()=>setChoice(id as string)}/>{icon}<span><b>{title}</b><small>{detail}</small></span></label>)}</div><div className="export-notice"><CircleAlert/><span><b>3 个页面尚未确认</b><small>默认不包含未确认页面、内部评论、AI 对话和未采用分支。</small></span></div></div><footer><button className="flow-secondary" onClick={onClose}>取消</button><button className="flow-primary" onClick={onClose}><Download/>创建导出任务</button></footer></section></div>}
function CommentsPanel({comments,selectedId,onLocate,onResolve,onReply,onEdit,onDelete,onQuote}:{comments:ProjectComment[];selectedId:number|null;onLocate:(id:number)=>void;onResolve:(id:number)=>void;onReply:(id:number,text:string)=>void;onEdit:(id:number,text:string)=>void;onDelete:(id:number)=>void;onQuote:(text:string)=>void}){
  const [filter,setFilter]=useState<'all'|'open'|'resolved'>('all');const [menuId,setMenuId]=useState<number|null>(null);const [replyId,setReplyId]=useState<number|null>(null);const [replyDraft,setReplyDraft]=useState('');const [editingId,setEditingId]=useState<number|null>(null);const [editDraft,setEditDraft]=useState('');
  useEffect(()=>{if(menuId===null)return;const closeMenu=(event:PointerEvent)=>{if(!(event.target as HTMLElement).closest('.comment-actions,.comment-more'))setMenuId(null)};document.addEventListener('pointerdown',closeMenu,true);return()=>document.removeEventListener('pointerdown',closeMenu,true)},[menuId]);
  const visible=comments.filter(comment=>filter==='all'||(filter==='resolved'?comment.resolved:!comment.resolved));
  const startReply=(comment:ProjectComment)=>{setMenuId(null);setEditingId(null);setReplyId(comment.id);setReplyDraft('')};
  const startEdit=(comment:ProjectComment)=>{setMenuId(null);setReplyId(null);setEditingId(comment.id);setEditDraft(comment.text)};
  return <div className="comments-panel"><div className="comments-filter"><button className={filter==='all'?'active':''} onClick={()=>setFilter('all')}>全部 {comments.length}</button><button className={filter==='open'?'active':''} onClick={()=>setFilter('open')}>未解决 {comments.filter(item=>!item.resolved).length}</button><button className={filter==='resolved'?'active':''} onClick={()=>setFilter('resolved')}>已解决 {comments.filter(item=>item.resolved).length}</button></div>{visible.length?visible.map(comment=><article className={(comment.resolved?'is-resolved ':'')+(selectedId===comment.id?'is-selected':'')} key={comment.id} onClick={()=>onLocate(comment.id)}><header><Avatar/><span><b>你</b><small>{comment.time}</small></span><em>{comment.number}</em><button className="comment-more" onClick={event=>{event.stopPropagation();setMenuId(menuId===comment.id?null:comment.id)}}><MoreHorizontal/></button>{menuId===comment.id&&<div className="comment-actions" onClick={event=>event.stopPropagation()}><button onClick={()=>startReply(comment)}><MessageCircle/>回复</button><button onClick={()=>{setMenuId(null);onQuote(comment.text)}}><WandSparkles/>在 AI 对话中引用</button><button onClick={()=>startEdit(comment)}><Pencil/>编辑</button><i/><button className="danger" onClick={()=>onDelete(comment.id)}><Trash2/>删除</button></div>}</header>{editingId===comment.id?<div className="comment-edit" onClick={event=>event.stopPropagation()}><textarea autoFocus value={editDraft} onChange={event=>setEditDraft(event.target.value)}/><footer><button onClick={()=>setEditingId(null)}>取消</button><button disabled={!editDraft.trim()} onClick={()=>{onEdit(comment.id,editDraft.trim());setEditingId(null)}}>保存</button></footer></div>:<p>{comment.text}</p>}{comment.resolved&&<div className="comment-resolved-status"><CircleCheck/>{comment.resolvedBy} 已解决 · {comment.resolvedAt}</div>}{comment.replies.length>0&&<div className="comment-thread">{comment.replies.map(reply=><div key={reply.id}><Avatar/><span><b>{reply.author}</b><small>{reply.time}</small><p>{reply.text}</p></span></div>)}</div>}{replyId===comment.id&&<div className="comment-reply" onClick={event=>event.stopPropagation()}><textarea autoFocus placeholder="回复这条评论…" value={replyDraft} onChange={event=>setReplyDraft(event.target.value)}/><footer><button onClick={()=>setReplyId(null)}>取消</button><button disabled={!replyDraft.trim()} onClick={()=>{onReply(comment.id,replyDraft.trim());setReplyId(null);setReplyDraft('')}}>回复</button></footer></div>}<footer onClick={event=>event.stopPropagation()}><button onClick={()=>onResolve(comment.id)}>{comment.resolved?'重新打开':'解决'}</button><button onClick={()=>startReply(comment)}><MessageCircle/>回复{comment.replies.length>0&&` ${comment.replies.length}`}</button></footer></article>):<div className="comments-empty"><MessageCircle/><b>{comments.length?'没有符合条件的评论':'还没有评论'}</b><small>{comments.length?'切换筛选条件查看其他评论。':'从画布的“修改 → 添加评论”开始标注。'}</small></div>}</div>
}
function ConfigPanel({tab,setTab,comments,selectedCommentId,onLocateComment,onResolveComment,onReplyComment,onEditComment,onDeleteComment,onQuoteComment}:{tab:string;setTab:(tab:string)=>void;comments:ProjectComment[];selectedCommentId:number|null;onLocateComment:(id:number)=>void;onResolveComment:(id:number)=>void;onReplyComment:(id:number,text:string)=>void;onEditComment:(id:number,text:string)=>void;onDeleteComment:(id:number)=>void;onQuoteComment:(text:string)=>void}){
  const [context,setContext]=useState(defaultProjectContext);const [draft,setDraft]=useState(context);const [contextOpen,setContextOpen]=useState(false);const [exportOpen,setExportOpen]=useState(false);const [editing,setEditing]=useState(false);
  const close=()=>{setContextOpen(false);setEditing(false);setDraft(context)};
  return <><aside className="config"><div className="config-top"><b>44345355</b><button className="export" onClick={()=>setExportOpen(true)}><Download/>导出项目</button></div><div className="tabs">{['配置','页面','评论'].map(x=><button className={tab===x?'active':''} onClick={()=>setTab(x)} key={x}>{x}{x==='评论'&&comments.filter(item=>!item.resolved).length>0&&<em>{comments.filter(item=>!item.resolved).length}</em>}</button>)}</div>{tab==='配置'?<div className="config-body"><Config title="项目背景"><button className="background" onClick={()=>setContextOpen(true)}><b>#角色</b><p>你是一个产品需求全流程协同助手，服务于产品团队从需求规划到UI设计的完整周期。</p><span>...</span></button></Config><Config title="设计规范"><Row>Design.md <em>主线</em><ChevronDown/></Row></Config><Config title="技能"><Row><span className="blue-dot" style={{backgroundImage:`url(${assets.leo})`}}/>Design.Skill</Row><Row muted><Plus/>添加更多Skill</Row></Config><Config title="技术规范"><Row muted>React</Row><Row muted>Ant Design</Row></Config><Config title="已生成资产"><Row muted>页面 <b>23</b></Row><Row muted>组件 <b>58</b></Row></Config></div>:tab==='评论'?<CommentsPanel comments={comments} selectedId={selectedCommentId} onLocate={onLocateComment} onResolve={onResolveComment} onReply={onReplyComment} onEdit={onEditComment} onDelete={onDeleteComment} onQuote={onQuoteComment}/>:<div className="empty-tab">页面内容</div>}</aside>{contextOpen&&<div className="context-modal-layer" onPointerDown={event=>{if(event.target===event.currentTarget)close()}}><section className="context-modal" role="dialog" aria-modal="true" aria-labelledby="context-title"><header><div><small>项目配置</small><h2 id="context-title">项目背景</h2></div><button onClick={close} aria-label="关闭"><X/></button></header><div className="context-editor"><textarea readOnly={!editing} value={draft} onChange={event=>setDraft(event.target.value)}/><div className="context-warning"><CircleAlert/><span>修改会更新 AI 的项目上下文，影响后续分析、生成与评审。</span></div></div><footer>{editing?<><button className="context-secondary" onClick={()=>{setEditing(false);setDraft(context)}}>取消</button><button className="context-primary" onClick={()=>{setContext(draft);setEditing(false)}}><Check/>保存修改</button></>:<button className="context-primary" onClick={()=>setEditing(true)}><Pencil/>编辑项目背景</button>}</footer></section></div>}{exportOpen&&<ProjectExportModal onClose={()=>setExportOpen(false)}/>}</>
}

