function AntReferencePreview({kind}:{kind:string}){
  if(kind==='ant-button')return <AntButton type="primary" size="small">主要按钮</AntButton>;
  if(kind==='ant-input')return <AntInput size="small" placeholder="请输入内容" readOnly/>;
  if(kind==='ant-select')return <AntSelect size="small" value="选项一" open={false} options={[{value:'选项一',label:'选项一'}]}/>;
  if(kind==='ant-switch')return <AntSwitch size="small" checked/>;
  if(kind==='ant-tag')return <AntTag color="blue">进行中</AntTag>;
  if(kind==='ant-progress')return <AntProgress percent={68} size="small" showInfo={false}/>;
  if(kind==='ant-avatar')return <AntAvatar size={30}>A</AntAvatar>;
  return <AntAlert title="操作成功" type="success" showIcon/>;
}
