function WorkspacePanelLegacy({tab,setTab,comments,selectedCommentId,onLocateComment,onResolveComment,onReplyComment,onEditComment,onDeleteComment,onQuoteComment}:{tab:string;setTab:(tab:string)=>void;comments:ProjectComment[];selectedCommentId:number|null;onLocateComment:(id:number)=>void;onResolveComment:(id:number)=>void;onReplyComment:(id:number,text:string)=>void;onEditComment:(id:number,text:string)=>void;onDeleteComment:(id:number)=>void;onQuoteComment:(text:string)=>void}){
  const [category,setCategory]=useState('全部');const [query,setQuery]=useState('');const [settingsOpen,setSettingsOpen]=useState(false);const [exportOpen,setExportOpen]=useState(false);const [reference,setReference]=useState<{item:AntReference;startX:number;startY:number;x:number;y:number;tracking:boolean}|null>(null);
  useEffect(()=>{if(!reference)return;const move=(event:PointerEvent)=>setReference(current=>current?.tracking?{...current,x:event.clientX,y:event.clientY}:current);const target=(event:Event)=>{const point=(event as CustomEvent<{clientX:number;clientY:number}>).detail;setReference(current=>current?{...current,x:point.clientX,y:point.clientY,tracking:false}:current)};const finish=()=>setReference(null);const key=(event:KeyboardEvent)=>{if(event.key==='Escape'){setReference(null);window.dispatchEvent(new Event('imagine-component-reference-cancel'))}};window.addEventListener('pointermove',move);window.addEventListener('imagine-component-reference-targeted',target);window.addEventListener('imagine-component-reference-complete',finish);window.addEventListener('keydown',key);return()=>{window.removeEventListener('pointermove',move);window.removeEventListener('imagine-component-reference-targeted',target);window.removeEventListener('imagine-component-reference-complete',finish);window.removeEventListener('keydown',key)}},[!!reference]);
  const visible=antReferences.filter(item=>(category==='全部'||category===item.group)&&(item.name.toLowerCase().includes(query.toLowerCase())||item.description.includes(query)));
  const startReference=(event:React.MouseEvent<HTMLElement>,item:AntReference)=>{const rect=event.currentTarget.getBoundingClientRect();const next={item,startX:rect.left,startY:rect.top+rect.height/2,x:rect.left-42,y:rect.top+rect.height/2,tracking:true};setReference(next);window.dispatchEvent(new CustomEvent('imagine-component-reference-start',{detail:item}))};
  const openTab=(next:string)=>{setTab(next);setReference(null);window.dispatchEvent(new Event('imagine-component-reference-cancel'))};
  return <><aside className="config workspace-panel imagine-library"><header className="imagine-library-toolbar"><div><button className={tab==='组件'?'active':''} onClick={()=>openTab('组件')} title="组件库"><Library/></button><button className={tab==='评论'?'active':''} onClick={()=>openTab('评论')} title="评论"><MessageCircle/>{comments.filter(comment=>!comment.resolved).length>0&&<em>{comments.filter(comment=>!comment.resolved).length}</em>}</button></div><span/><button onClick={()=>setSettingsOpen(true)} title="项目设置"><SlidersHorizontal/></button><button onClick={()=>setExportOpen(true)} title="导出项目"><Download/></button></header>{tab==='组件'?<div className="imagine-library-body"><label className="imagine-library-search"><Search/><input value={query} onChange={event=>setQuery(event.target.value)} placeholder="搜索 Ant Design 组件"/>{query&&<button onClick={()=>setQuery('')}><X/></button>}</label><div className="imagine-library-source"><span><b>Ant Design</b><small>官方代码组件</small></span><a href="https://ant.design/components/overview-cn/" target="_blank" rel="noreferrer" title="查看 Ant Design 组件文档"><ExternalLink/></a></div><div className="imagine-library-categories">{['全部','通用','数据录入','数据展示','反馈'].map(item=><button className={category===item?'active':''} onClick={()=>setCategory(item)} key={item}>{item}</button>)}</div><div className="imagine-library-heading"><b>组件参考</b><small>{visible.length} 个</small></div><div className="imagine-ant-grid">{visible.map(item=><article role="button" tabIndex={0} className={reference?.item.kind===item.kind?'selected':''} onClick={event=>startReference(event,item)} onKeyDown={event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();startReference(event as unknown as React.MouseEvent<HTMLElement>,item)}}} key={item.kind}><span className="imagine-ant-preview"><AntReferencePreview kind={item.kind}/></span><span><b>{item.name}</b><small>{item.description}</small></span>{reference?.item.kind===item.kind&&<Check/>}</article>)}</div>{visible.length===0&&<div className="component-empty"><Search/><b>没有找到组件</b><small>换一个名称或分类试试。</small></div>}<footer className={'imagine-reference-tip '+(reference?'active':'')}><Component/><span><b>{reference?'已选择 '+reference.item.name:'选择组件作为代码参考'}</b><small>{reference?'点击画布中的目标位置，随后选择范围':'组件不会直接拖入画布，由 AI 结合目标区域修改代码'}</small></span>{reference&&<button onClick={()=>{setReference(null);window.dispatchEvent(new Event('imagine-component-reference-cancel'))}}><X/></button>}</footer></div>:<CommentsPanel comments={comments} selectedId={selectedCommentId} onLocate={onLocateComment} onResolve={onResolveComment} onReply={onReplyComment} onEdit={onEditComment} onDelete={onDeleteComment} onQuote={onQuoteComment}/>}</aside>{reference&&<svg className="component-reference-line" aria-hidden="true"><defs><marker id="reference-arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z"/></marker></defs><path d={'M '+reference.startX+' '+reference.startY+' C '+(reference.startX-80)+' '+reference.startY+', '+(reference.x+80)+' '+reference.y+', '+reference.x+' '+reference.y} markerEnd="url(#reference-arrow)"/></svg>}{settingsOpen&&<div className="workspace-settings-layer" onPointerDown={event=>{if(event.target===event.currentTarget)setSettingsOpen(false)}}><section className="workspace-settings"><header><div><small>项目设置</small><h2>速学慧 H5</h2></div><button onClick={()=>setSettingsOpen(false)}><X/></button></header><div><Row><SlidersHorizontal/>核心设计规范 <b>Imagine Design v1.3</b></Row><Row><Zap/>项目能力 <b>已启用 4 项</b></Row><Row><Code2/>技术规范 <b>React + TypeScript</b></Row><Row><Cloud/>存储位置 <b>本地工作区</b></Row></div><footer><button onClick={()=>setSettingsOpen(false)}>完成</button></footer></section></div>}{exportOpen&&<ProjectExportModal onClose={()=>setExportOpen(false)}/>}</>
}
function WorkspacePanel({tab,setTab,comments,selectedCommentId,onLocateComment,onResolveComment,onReplyComment,onEditComment,onDeleteComment,onQuoteComment}:{tab:string;setTab:(tab:string)=>void;comments:ProjectComment[];selectedCommentId:number|null;onLocateComment:(id:number)=>void;onResolveComment:(id:number)=>void;onReplyComment:(id:number,text:string)=>void;onEditComment:(id:number,text:string)=>void;onDeleteComment:(id:number)=>void;onQuoteComment:(text:string)=>void}){
  const [category,setCategory]=useState('全部');
  const [query,setQuery]=useState('');
  const [panelOpen,setPanelOpen]=useState(true);
  const [pinned,setPinned]=useState(false);
  const [reference,setReference]=useState<{item:AntReference;startX:number;startY:number;x:number;y:number;tracking:boolean}|null>(null);
  useEffect(()=>{if(!reference)return;setPanelOpen(true);const move=(event:PointerEvent)=>setReference(current=>current?.tracking?{...current,x:event.clientX,y:event.clientY}:current);const target=(event:Event)=>{const point=(event as CustomEvent<{clientX:number;clientY:number}>).detail;setReference(current=>current?{...current,x:point.clientX,y:point.clientY,tracking:false}:current)};const finish=()=>setReference(null);const key=(event:KeyboardEvent)=>{if(event.key==='Escape'){setReference(null);window.dispatchEvent(new Event('imagine-component-reference-cancel'))}};window.addEventListener('pointermove',move);window.addEventListener('imagine-component-reference-targeted',target);window.addEventListener('imagine-component-reference-complete',finish);window.addEventListener('keydown',key);return()=>{window.removeEventListener('pointermove',move);window.removeEventListener('imagine-component-reference-targeted',target);window.removeEventListener('imagine-component-reference-complete',finish);window.removeEventListener('keydown',key)}},[!!reference]);
  useEffect(()=>{if(!panelOpen||pinned||reference)return;const dismiss=(event:PointerEvent)=>{const target=event.target as HTMLElement;if(target.closest('.workspace-panel')||target.closest('.workspace-panel-open'))return;closePanel()};document.addEventListener('pointerdown',dismiss,true);return()=>document.removeEventListener('pointerdown',dismiss,true)},[panelOpen,pinned,!!reference]);
  const visible=antReferences.filter(item=>(category==='全部'||category===item.group)&&(item.name.toLowerCase().includes(query.toLowerCase())||item.description.includes(query)));
  const startReference=(event:React.MouseEvent<HTMLElement>,item:AntReference)=>{const rect=event.currentTarget.getBoundingClientRect();setReference({item,startX:rect.left,startY:rect.top+rect.height/2,x:rect.left-42,y:rect.top+rect.height/2,tracking:true});window.dispatchEvent(new CustomEvent('imagine-component-reference-start',{detail:item}))};
  const openTab=(next:string)=>{setTab(next);setReference(null);window.dispatchEvent(new Event('imagine-component-reference-cancel'))};
  const closePanel=()=>{if(reference)return;setPanelOpen(false);window.dispatchEvent(new Event('imagine-component-reference-cancel'))};
  return <>
    {!panelOpen&&<button className="workspace-panel-open" onPointerEnter={()=>setPanelOpen(true)} onClick={()=>setPanelOpen(true)} title="展开右侧边栏"><PanelRight/></button>}
    {panelOpen&&<aside className="config workspace-panel imagine-library">
      <header className="imagine-library-toolbar">
        <div><button className={tab==='组件'?'active':''} onClick={()=>openTab('组件')} title="组件库"><Library/></button><button className={tab==='评论'?'active':''} onClick={()=>openTab('评论')} title="评论"><MessageCircle/>{comments.filter(comment=>!comment.resolved).length>0&&<em>{comments.filter(comment=>!comment.resolved).length}</em>}</button></div>
        <span/>
        <button className={pinned?'is-pinned':''} aria-pressed={pinned} onClick={()=>setPinned(value=>!value)} title={pinned?'取消固定右侧边栏':'固定右侧边栏'}><Pin/></button>
        <button onClick={closePanel} title="关闭右侧边栏"><X/></button>
      </header>
      {tab==='组件'?<div className="imagine-library-body">
        <label className="imagine-library-search"><Search/><input value={query} onChange={event=>setQuery(event.target.value)} placeholder="搜索组件"/>{query&&<button onClick={()=>setQuery('')}><X/></button>}</label>
        <div className="imagine-library-categories">{['全部','通用','数据录入','数据展示','反馈'].map(item=><button className={category===item?'active':''} onClick={()=>setCategory(item)} key={item}>{item}</button>)}</div>
        <div className="imagine-library-heading"><b>组件参考</b><small>{visible.length} 个</small></div>
        <div className="imagine-ant-grid">{visible.map(item=><article role="button" tabIndex={0} className={reference?.item.kind===item.kind?'selected':''} onClick={event=>startReference(event,item)} onKeyDown={event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();startReference(event as unknown as React.MouseEvent<HTMLElement>,item)}}} key={item.kind}><span className="imagine-ant-preview"><AntReferencePreview kind={item.kind}/></span><span><b>{item.name}</b><small>{item.description}</small></span>{reference?.item.kind===item.kind&&<Check/>}</article>)}</div>
        {visible.length===0&&<div className="component-empty"><Search/><b>没有找到组件</b><small>换一个名称或分类试试。</small></div>}
      </div>:<CommentsPanel comments={comments} selectedId={selectedCommentId} onLocate={onLocateComment} onResolve={onResolveComment} onReply={onReplyComment} onEdit={onEditComment} onDelete={onDeleteComment} onQuote={onQuoteComment}/>} 
      {tab==='组件'&&<div className="library-operation-help"><button><Info/>操作提示</button><div className="operation-guide-popover" aria-hidden="true"><div className="operation-guide-scene"><i className="guide-canvas"><span/></i><svg viewBox="0 0 180 96"><path d="M151 30 C125 23 112 67 74 59"/><path d="M76 52 L66 59 L76 66"/></svg><i className="guide-component"><span/><span/></i><i className="guide-cursor"/></div></div></div>}
    </aside>}
    {reference&&<svg className="component-reference-line" aria-hidden="true"><defs><marker id="reference-arrow-v2" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z"/></marker></defs><path d={'M '+reference.startX+' '+reference.startY+' C '+(reference.startX-80)+' '+reference.startY+', '+(reference.x+80)+' '+reference.y+', '+reference.x+' '+reference.y} markerEnd="url(#reference-arrow-v2)"/></svg>}
  </>
}
function Config({title,children}:{title:string,children:React.ReactNode}){return <section className="config-section"><h3>{title}</h3><div className="config-stack">{children}</div></section>}
function Row({children,muted=false}:{children:React.ReactNode,muted?:boolean}){return <div className={'row '+(muted?'muted':'')}>{children}</div>}
function Project({goHome}:{goHome:()=>void}){const [collapsed,setCollapsed]=useState(true);const [configTab,setConfigTab]=useState('组件');const [comments,setComments]=useState<ProjectComment[]>([]);const [focusRequest,setFocusRequest]=useState<CommentFocus>(null);const [selectedCommentId,setSelectedCommentId]=useState<number|null>(null);const [quotedComments,setQuotedComments]=useState<string[]>([]);const addComments=(items:ProjectComment[])=>{setComments(current=>{const max=current.reduce((value,item)=>Math.max(value,item.number),0);return [...items.map((item,index)=>({...item,number:max+index+1})),...current]});setConfigTab('评论')};const locateComment=(id:number)=>{setSelectedCommentId(id);setFocusRequest({id,nonce:Date.now()});setConfigTab('评论')};const resolveComment=(id:number)=>setComments(current=>current.map(comment=>comment.id!==id?comment:comment.resolved?{...comment,resolved:false,resolvedBy:undefined,resolvedAt:undefined}:{...comment,resolved:true,resolvedBy:'你',resolvedAt:'刚刚'}));const replyComment=(id:number,text:string)=>setComments(current=>current.map(comment=>comment.id===id?{...comment,replies:[...comment.replies,{id:Date.now(),author:'你',text,time:'刚刚'}]}:comment));const editComment=(id:number,text:string)=>setComments(current=>current.map(comment=>comment.id===id?{...comment,text}:comment));const deleteComment=(id:number)=>{setComments(current=>current.filter(comment=>comment.id!==id));if(selectedCommentId===id)setSelectedCommentId(null)};const quoteComment=(text:string)=>setQuotedComments(current=>[...current,text]);return <div className="project-page"><HomeSidebar collapsed={collapsed} active="project" goHome={goHome} goProject={()=>{}}/><div className="project-shell"><Header crumb="首页 / 速学慧 H5" online onToggleSidebar={()=>setCollapsed(v=>!v)}/><div className="stage"><PageStructurePanel/><DotCanvas comments={comments} focusRequest={focusRequest} onAddComments={addComments} onSelectComment={locateComment}/><Composer quotedComments={quotedComments} onClearQuote={index=>setQuotedComments(current=>current.filter((_,itemIndex)=>itemIndex!==index))}/><WorkspacePanel tab={configTab} setTab={setConfigTab} comments={comments} selectedCommentId={selectedCommentId} onLocateComment={locateComment} onResolveComment={resolveComment} onReplyComment={replyComment} onEditComment={editComment} onDeleteComment={deleteComment} onQuoteComment={quoteComment}/></div></div></div>}
const areaMeta:Record<Exclude<AppPage,'home'|'project'>,{title:string;desc:string}>={projects:{title:'项目',desc:'导入并管理团队已有项目，在同一套规则上持续延展页面。'},assets:{title:'资产库',desc:'集中查看可复用的代码组件；用户看到的是可直接使用的真实视觉组件。'},specs:{title:'设计规范',desc:'管理团队已确认的核心规范版本，项目页面默认继承，不在画布中随意改写。'},skills:{title:'技能库',desc:'用直观的专家能力帮助团队生成、识别、检查与交付。'},connectors:{title:'连接器',desc:'连接设计、代码与内部存储来源，并按需同步增量变化。'},team:{title:'团队设置',desc:'管理成员、审核角色和资产确认权限。'}};
function ProductAreaPage({page,onNavigate}:{page:Exclude<AppPage,'home'|'project'>;onNavigate:(page:AppPage)=>void}){const [collapsed,setCollapsed]=useState(false);const meta=areaMeta[page];const projectCards=[['速学慧','Figma · 已连接','18 个页面'],['想象力智能中高考','GitHub · 已连接','12 个页面'],['代理商小程序','Figma · 待同步','9 个页面']];return <div className="home-page product-area-page"><HomeSidebar goProject={()=>onNavigate('project')} goHome={()=>onNavigate('home')} onNavigate={onNavigate} collapsed={collapsed} active={page}/><main className="home-main"><Header crumb={meta.title} onToggleSidebar={()=>setCollapsed(value=>!value)}/><div className="product-area-content"><header><div><small>Imagine Lab</small><h1>{meta.title}</h1><p>{meta.desc}</p></div>{page==='projects'&&<button className="area-primary"><Import/>导入项目</button>}</header>{page==='projects'?<div className="area-project-grid">{projectCards.map(([name,source,count])=><button onClick={()=>onNavigate('project')} key={name}><span><FolderKanban/></span><div><b>{name}</b><small>{source}</small></div><em>{count}</em><ChevronRight/></button>)}</div>:page==='assets'?<><div className="area-toolbar"><label><Search/><input placeholder="搜索组件、用途或来源项目"/></label>{['全部组件','项目组件','核心组件','待确认'].map((item,index)=><button className={index===0?'active':''} key={item}>{item}</button>)}</div><div className="area-component-grid">{workspaceComponents.map(([name,kind,group])=><article key={name}><ComponentPreview kind={kind}/><footer><span><b>{name}</b><small>速学慧 · {group}</small></span><button><MoreHorizontal/></button></footer></article>)}</div></>:page==='specs'?<div className="area-list">{[['Imagine Design','v1.3 · 团队核心规范','已锁定'],['商城后台规范','v2.1 · 订单与经营后台','已发布'],['移动端轻量规范','v0.9 · H5 与小程序','待确认']].map(([name,detail,status])=><button key={name}><SlidersHorizontal/><span><b>{name}</b><small>{detail}</small></span><em>{status}</em><ChevronRight/></button>)}</div>:page==='skills'?<div className="expert-grid">{[[<WandSparkles/>,'页面生成专家','遵循项目规范并优先复用已有组件'],[<Component/>,'组件识别专家','从页面和代码中识别可复用 UI 组件'],[<ShieldCheck/>,'规范检查专家','检查页面是否偏离团队设计规则'],[<Archive/>,'交付整理专家','整理前端页面、依赖与使用说明']].map(([icon,name,detail])=><article key={name as string}><span>{icon}</span><b>{name}</b><p>{detail}</p><button>查看能力<ChevronRight/></button></article>)}</div>:page==='connectors'?<div className="connector-list">{[['F','Figma','设计项目与组件来源','已连接'],['G','GitHub','前端仓库与页面来源','已连接'],['亿','亿方云','内部资产、版本与交付存储','未连接']].map(([mark,name,detail,status])=><article key={name}><i>{mark}</i><span><b>{name}</b><small>{detail}</small></span><em className={status==='已连接'?'connected':''}>{status}</em><button>{status==='已连接'?'管理':'连接'}<ChevronRight/></button></article>)}</div>:<div className="team-settings-grid"><section><header><Users/><span><b>团队成员</b><small>管理成员与工作角色</small></span><button><UserPlus/>邀请成员</button></header>{[['Leo','产品设计师'],['Lily','产品经理'],['雅木茶','前端工程师']].map(([name,role])=><div key={name}><Avatar/><span><b>{name}</b><small>{role}</small></span><em>成员</em><MoreHorizontal/></div>)}</section><section className="permission-card"><header><ShieldCheck/><span><b>资产审核权限</b><small>只有审核人可将临时组件加入核心资产库</small></span></header><label><span>项目组件确认</span><b>项目负责人</b></label><label><span>核心组件归档</span><b>设计系统维护者</b></label><label><span>设计规范发布</span><b>设计负责人</b></label></section></div>}</div></main></div>}

function App(){const [page,setPage]=useState<AppPage>('home');useEffect(()=>{const navigate=(event:MouseEvent)=>{const title=(event.target as HTMLElement).closest('button[title]')?.getAttribute('title');const map:Record<string,AppPage>={'项目':'projects','资产库':'assets','设计规范':'specs','技能库':'skills','连接器':'connectors','团队设置':'team'};if(title&&map[title])setPage(map[title])};document.addEventListener('click',navigate);return()=>document.removeEventListener('click',navigate)},[]);if(page==='home')return <Home goProject={()=>setPage('project')}/>;if(page==='project')return <Project goHome={()=>setPage('home')}/>;return <ProductAreaPageV2 page={page} onNavigate={setPage}/>}

type ExpertHubTab='design'|'skills'|'connectors';
type ExpertItem={id:number;name:string;role:string;description:string;portrait:string;tag:string};
type ConnectorItem={id:number;name:string;description:string;tone:string;connected:boolean;mark:string;logo:string};
type AssetStatus='项目组件'|'核心组件'|'待确认'|'已停用';
type AssetFilter='全部'|AssetStatus;
type ComponentAssetItem={id:number;name:string;kind:string;group:string;project:string;status:AssetStatus;updated:string;version:string;uses:number;description:string};

const paperLineExperts=[
  {name:'中高考UI设计师',description:'面向中高考学习产品，统一课程、题库、测评与学习进度等核心场景的界面体验。',owner:'Imagine AI',users:'1.2k',image:'https://app.paper.design/file-assets/01KRD2WZQT7EB357T4XB9BT72D/0NHJNN4J9GXW39VN7K3BRQHNYE.avif'},
  {name:'代理商业务UI设计师',description:'面向代理商管理与经营场景，优化客户、订单、业绩和数据看板等业务界面。',owner:'Imagine AI',users:'1.6k',image:'https://app.paper.design/file-assets/01KRD2WZQT7EB357T4XB9BT72D/75G91M0MCYHXP1TPJVF04ND9V4.avif',selected:true},
  {name:'速学慧UI设计师',description:'围绕速学慧的学习路径与品牌规范，设计课程、任务、练习和成长反馈界面。',owner:'王刚',users:'1.9k',image:'https://app.paper.design/file-assets/01KRD2WZQT7EB357T4XB9BT72D/69AJDPXFCRKZS82V4KWVAZ0XXA.avif'},
  {name:'移动端体验设计师',description:'专注移动端的信息层级、触控操作与响应式布局，提升小屏场景下的使用效率。',owner:'Imagine AI',users:'1.2k',image:'https://app.paper.design/file-assets/01KRD2WZQT7EB357T4XB9BT72D/7CW7BE7P7XAAZZ8TBYNE0EAYJ7.avif'},
  {name:'品牌设计专员',description:'将品牌色彩、字体、图形与视觉语气落实到产品界面，保持品牌表达统一。',owner:'Imagine AI',users:'1.9k',image:'https://app.paper.design/file-assets/01KRD2WZQT7EB357T4XB9BT72D/0266CFFVGXPGHJMPF0FXVEBQ0B.avif'}
];

function PaperCategoryIcon({kind}:{kind:ExpertHubTab}){
  if(kind==='design')return <svg viewBox="0 0 24 24" aria-hidden="true"><rect width="18" height="18" x="3" y="3" rx="2"/><path d="M9 3v18"/><path d="M9 15h12"/></svg>;
  if(kind==='skills')return <svg viewBox="0 0 24 24" aria-hidden="true"><path d="M21 8a2 2 0 0 0-1-1.73l-7-4a2 2 0 0 0-2 0l-7 4A2 2 0 0 0 3 8v8a2 2 0 0 0 1 1.73l7 4a2 2 0 0 0 2 0l7-4A2 2 0 0 0 21 16Z"/><path d="m3.3 7 8.7 5 8.7-5"/><path d="M12 22V12"/></svg>;
  return <svg viewBox="0 0 24 24" aria-hidden="true"><path d="m18 16 4-4-4-4"/><path d="m6 8-4 4 4 4"/><path d="m14.5 4-5 16"/></svg>;
}

type PaperCatalogItem={name:string;description:string;owner:string;users:string;image?:string;portrait?:string;tone?:string;mark?:string;logo?:string;selected?:boolean;connectorId?:number;connected?:boolean};
type MySkillComponent={id:number;name:string;description:string;users:string;image:string};

function PaperLineExperts({tab,onTab,onAdd,designExperts,skillExperts,connectors,onToggleConnector,myComponents,managing,onManage,onCancelManage,onDeleteComponent}:{tab:ExpertHubTab;onTab:(tab:ExpertHubTab)=>void;onAdd:()=>void;designExperts:ExpertItem[];skillExperts:ExpertItem[];connectors:ConnectorItem[];onToggleConnector:(id:number)=>void;myComponents:MySkillComponent[];managing:boolean;onManage:()=>void;onCancelManage:()=>void;onDeleteComponent:(id:number)=>void}){
  const [query,setQuery]=useState('');
  useEffect(()=>setQuery(''),[tab]);
  const customDesignItems:PaperCatalogItem[]=designExperts.map((item,index)=>({name:item.name,description:item.description,owner:'我的团队',users:'新建',portrait:item.portrait,selected:index===0}));
  const skillItems:PaperCatalogItem[]=skillExperts.map((item,index)=>({name:item.name,description:item.description,owner:'Imagine AI',users:['2.3k','1.8k','1.5k','1.1k','986','1.4k'][index]||'新建',portrait:item.portrait,selected:index===0}));
  const connectorItems:PaperCatalogItem[]=connectors.map(item=>({name:item.name,description:item.description,owner:'官方连接器',users:item.connected?'已连接':'未连接',tone:item.tone,mark:item.mark,logo:item.logo,connectorId:item.id,connected:item.connected,selected:item.connected}));
  const items:PaperCatalogItem[]=(tab==='design'?[...paperLineExperts,...customDesignItems]:tab==='skills'?skillItems:connectorItems).filter(item=>`${item.name}${item.description}${item.owner}`.toLowerCase().includes(query.trim().toLowerCase()));
  const addTitle='添加专家';
  const addDescription='上传或创建自己的专家';
  const sectionTitle=tab==='connectors'?'官方连接器':'官方技能';
  const searchPlaceholder=tab==='connectors'?'搜索连接器':tab==='skills'?'搜索技能专家':'搜索专家';
  return <div className="paper-line-canvas">
    <div className="paper-line-content">
      {myComponents.length===0?<div className="paper-line-add-row"><button type="button" className="paper-line-add-card" onClick={onAdd}><span><Plus/></span><span><b>{addTitle}</b><small>{addDescription}</small></span></button></div>:<section className={'paper-my-components '+(managing?'managing':'')}>
        <header><h2>我的组件</h2>{managing?<button type="button" className="paper-my-cancel" onClick={onCancelManage}>取消</button>:<div><button type="button" onClick={onAdd}><Plus/>添加 专家</button><button type="button" onClick={onManage}><Settings/>管理 专家</button></div>}</header>
        <div className="paper-my-grid">{myComponents.map(item=><article className="paper-my-card" key={item.id}><div className="paper-my-body"><span className="paper-my-image" style={{backgroundImage:`url(${item.image})`}}/><span className="paper-my-copy"><b>{item.name}</b><p>{item.description}</p><span><Users/>{item.users}</span></span></div>{managing&&<button type="button" className="paper-my-delete" aria-label={`删除 ${item.name}`} onClick={()=>onDeleteComponent(item.id)}><Trash2/></button>}</article>)}</div>
      </section>}
      <section className={'paper-line-official '+(myComponents.length?'after-my-components':'')}>
        <div className="paper-line-directory-head">
          <div className="paper-line-directory-left"><h2>{sectionTitle}</h2><div className="paper-line-categories" role="tablist">
            {([['design','设计专家'],['skills','技能专家'],['connectors','连接器']] as [ExpertHubTab,string][]).map(([kind,label])=><button type="button" role="tab" aria-selected={tab===kind} className={tab===kind?'active':''} onClick={()=>onTab(kind)} key={kind}><PaperCategoryIcon kind={kind}/><span>{label}</span></button>)}
          </div></div>
          <label className="paper-line-search"><Search/><input value={query} onChange={event=>setQuery(event.target.value)} placeholder={searchPlaceholder}/></label>
        </div>
        <div className="paper-line-expert-grid">
          {items.map(item=><article className={'paper-line-expert-card '+(item.selected?'selected ':'')+(item.connectorId?'connector-card':'')} key={item.name}>
            <div className="paper-line-expert-body">
              {item.connectorId?<span className={'paper-line-expert-image paper-line-connector-image '+item.tone}><img src={item.logo} alt={`${item.name} 官方 Logo`}/></span>:<span className="paper-line-expert-image" style={item.image?{backgroundImage:`url(${item.image})`}:{backgroundImage:"url('/expert-portraits-atlas.png')",backgroundPosition:item.portrait,backgroundSize:'300% 200%'}}/>}
              <span className="paper-line-expert-copy"><b>{item.name}</b><p>{item.description}</p><span className="paper-line-expert-meta"><span>{item.owner}</span><i>·</i>{item.connectorId?<button type="button" className={item.connected?'connected':''} onClick={()=>onToggleConnector(item.connectorId!)}>{item.connected?<><Check/>已连接</>:<>连接</>}</button>:<span className="paper-line-users"><Users/><span>{item.users}</span></span>}</span></span>
            </div>
            {!item.connectorId&&item.selected&&<span className="paper-line-selected"><Check/></span>}
          </article>)}
        </div>
        {items.length===0&&<div className="paper-line-empty"><Search/><b>没有找到结果</b><small>换个关键词试试</small></div>}
      </section>
    </div>
  </div>;
}

function ProductAreaPageV3({page,onNavigate}:{page:Exclude<AppPage,'home'|'project'>;onNavigate:(page:AppPage)=>void}){
  const [collapsed,setCollapsed]=useState(false);
  const [tab,setTab]=useState<ExpertHubTab>(page==='connectors'?'connectors':page==='skills'?'skills':'design');
  const [addOpen,setAddOpen]=useState(false);
  const [managingComponents,setManagingComponents]=useState(false);
  const [myComponents,setMyComponents]=useState<MySkillComponent[]>([]);
  const [menuId,setMenuId]=useState<number|null>(null);
  const [renamingId,setRenamingId]=useState<number|null>(null);
  const [draftName,setDraftName]=useState('');
  const [projects,setProjects]=useState([
    {id:1,name:'速学慧',modified:'8 分钟前'},
    {id:2,name:'想象力智能中高考',modified:'2 小时前'},
    {id:3,name:'代理商小程序',modified:'1 天前'},
    {id:4,name:'品牌活动中心',modified:'5 天前'}
  ]);
  const [assetQuery,setAssetQuery]=useState('');
  const [assetFilter,setAssetFilter]=useState<AssetFilter>('全部');
  const [selectedAssetId,setSelectedAssetId]=useState<number|null>(1);
  const [componentAssets,setComponentAssets]=useState<ComponentAssetItem[]>([
    {id:1,name:'学习任务卡',kind:'task',group:'内容',project:'速学慧',status:'核心组件',updated:'12 分钟前',version:'v2.4',uses:38,description:'展示今日学习任务、学科与预计用时，用于首页和学习计划页。'},
    {id:2,name:'学习进度环',kind:'progress',group:'数据',project:'速学慧',status:'项目组件',updated:'1 小时前',version:'v1.8',uses:21,description:'用环形进度表达阶段目标完成度，支持百分比与辅助说明。'},
    {id:3,name:'课程信息卡',kind:'course',group:'内容',project:'速学慧',status:'待确认',updated:'3 小时前',version:'v0.6',uses:6,description:'承载课程封面、课程名称和继续学习入口，等待项目负责人确认。'},
    {id:4,name:'移动端底部导航',kind:'nav',group:'导航',project:'智能中高考',status:'核心组件',updated:'1 天前',version:'v3.1',uses:54,description:'移动端四栏主导航，包含默认、选中与禁用状态。'},
    {id:5,name:'主要行动按钮',kind:'button',group:'基础',project:'代理商小程序',status:'项目组件',updated:'2 天前',version:'v1.2',uses:73,description:'团队通用主要操作按钮，统一高度、圆角、图标和交互反馈。'},
    {id:6,name:'学习数据卡',kind:'stats',group:'数据',project:'智能中高考',status:'待确认',updated:'3 天前',version:'v0.9',uses:9,description:'展示周期学习趋势和关键变化，当前仍需确认数据密度。'},
    {id:7,name:'学习成果分享卡',kind:'share',group:'内容',project:'速学慧',status:'项目组件',updated:'4 天前',version:'v1.0',uses:15,description:'生成适合分享的学习成果摘要，支持品牌信息与分享入口。'},
    {id:8,name:'旧版任务入口',kind:'task',group:'内容',project:'速学慧',status:'已停用',updated:'2 周前',version:'v0.4',uses:0,description:'旧版任务入口，已由学习任务卡替代，保留用于历史页面兼容。'}
  ]);
  const [designExperts,setDesignExperts]=useState<ExpertItem[]>([]);
  const [skillExperts,setSkillExperts]=useState<ExpertItem[]>([
    {id:11,name:'页面生成专家',role:'页面延展',description:'遵循项目规范并优先复用已有组件，生成可继续编辑的前端 UI 页面。',portrait:'0% 0%',tag:'已安装'},
    {id:12,name:'组件识别专家',role:'资产沉淀',description:'从导入页面与代码中识别组件族、变体和可复用结构。',portrait:'50% 0%',tag:'已安装'},
    {id:13,name:'规范检查专家',role:'质量检查',description:'发现页面偏离核心设计规范的地方，并给出可执行的修正建议。',portrait:'100% 0%',tag:'已安装'},
    {id:14,name:'Figma 导入向导',role:'设计项目导入',description:'分层读取设计文件，先建立索引，再按需转换页面和组件，节省模型额度。',portrait:'0% 100%',tag:'系统'},
    {id:15,name:'代码项目导入向导',role:'代码项目导入',description:'先识别路由、样式与组件入口，再提取前端 UI，避免无差别读取完整仓库。',portrait:'50% 100%',tag:'系统'},
    {id:16,name:'交付整理专家',role:'前端交付',description:'整理页面代码、依赖与组件使用说明，形成前端可以接手的交付内容。',portrait:'100% 100%',tag:'已安装'}
  ]);
  const [connectors,setConnectors]=useState<ConnectorItem[]>([
    {id:21,name:'Figma',description:'同步设计页面、组件与变量来源。',tone:'figma',connected:true,mark:'F',logo:'https://cdn.simpleicons.org/figma'},
    {id:22,name:'GitHub',description:'连接前端代码仓库与版本记录。',tone:'github',connected:true,mark:'G',logo:'https://cdn.simpleicons.org/github/181717'},
    {id:23,name:'亿方云',description:'保存团队资产、交付包与版本快照。',tone:'cloud',connected:false,mark:'亿',logo:'https://s3.ssl.qhres2.com/static/350d137d32673213.svg'},
    {id:24,name:'飞书',description:'读取项目文档并接收团队协作消息。',tone:'feishu',connected:true,mark:'飞',logo:'/source-logos/feishu.ico'},
    {id:25,name:'Notion',description:'导入产品资料与结构化项目文档。',tone:'notion',connected:false,mark:'N',logo:'/source-logos/notion.ico'},
    {id:26,name:'Obsidian',description:'读取本地 Markdown 产品资料。',tone:'obsidian',connected:false,mark:'O',logo:'/source-logos/obsidian.svg'},
    {id:27,name:'蓝湖',description:'通过受控浏览读取产品文档文本。',tone:'lanhu',connected:false,mark:'蓝',logo:'/source-logos/lanhu.ico'},
    {id:28,name:'墨刀',description:'通过受控浏览读取项目说明文本。',tone:'modao',connected:false,mark:'墨',logo:'/source-logos/modao.ico'}
  ]);
  useEffect(()=>{if(page==='connectors')setTab('connectors');else if(page==='skills')setTab('skills');else if(page==='specs')setTab('design')},[page]);
  useEffect(()=>{const close=()=>setMenuId(null);document.addEventListener('click',close);return()=>document.removeEventListener('click',close)},[]);
  const commitRename=(id:number)=>{const next=draftName.trim();if(next)setProjects(items=>items.map(item=>item.id===id?{...item,name:next}:item));setRenamingId(null)};
  const addSkillComponent=(name:string,description:string)=>{
    setMyComponents(items=>[...items,{id:Date.now(),name,description,users:'1.6k',image:'https://app.paper.design/file-assets/01KRD2WZQT7EB357T4XB9BT72D/1W9CB9B82ZK9CW9CRYQQMAFGM1.png'}]);
    setManagingComponents(false);
    setAddOpen(false);
  };
  const renderExpertCard=(item:ExpertItem)=><button type="button" className="expert-profile-card" key={item.id}>
    <span className="expert-portrait" style={{backgroundPosition:item.portrait}}/>
    <span className="expert-copy"><span className="expert-title-row"><b>{item.name}</b><em>{item.tag}</em></span><small>{item.role}</small><p>{item.description}</p></span>
    <ChevronRight/>
  </button>;
  const isProjects=page==='projects';
  const isAssets=page==='assets';
  const assetFilters:AssetFilter[]=['全部','项目组件','核心组件','待确认','已停用'];
  const visibleAssets=componentAssets.filter(item=>(assetFilter==='全部'||item.status===assetFilter)&&`${item.name}${item.group}${item.project}${item.description}`.toLowerCase().includes(assetQuery.trim().toLowerCase()));
  const selectedAsset=componentAssets.find(item=>item.id===selectedAssetId)||null;
  const updateAssetStatus=(id:number,status:AssetStatus)=>setComponentAssets(items=>items.map(item=>item.id===id?{...item,status,updated:'刚刚'}:item));
  return <div className="home-page product-area-page expert-workspace-page">
    <HomeSidebar collapsed={collapsed} active={page} goHome={()=>onNavigate('home')} goProject={()=>onNavigate('project')} onNavigate={onNavigate}/>
    <main className="home-main"><Header crumb={isProjects?'项目':isAssets?'资产库':'专家与连接'} onToggleSidebar={()=>setCollapsed(v=>!v)}/>
      {isProjects?<div className="product-area-content product-area-v2 project-management-v3">
        <header className="area-header"><div><h1>项目</h1><p>管理已导入并持续迭代的设计与前端项目</p></div><button type="button" className="primary-area-action" onClick={()=>onNavigate('home')}><Import/>导入项目</button></header>
        <div className="area-project-grid project-card-grid">
          {projects.map(project=><article className="area-project-card project-manage-card" key={project.id}>
            <button type="button" className="project-open" onClick={()=>onNavigate('project')}>
              <span className="project-card-icon"><FolderKanban/></span>
              <span>{renamingId===project.id?<input autoFocus value={draftName} onChange={event=>setDraftName(event.target.value)} onClick={event=>event.stopPropagation()} onBlur={()=>commitRename(project.id)} onKeyDown={event=>{if(event.key==='Enter')commitRename(project.id);if(event.key==='Escape')setRenamingId(null)}}/>:<b>{project.name}</b>}<small>{project.modified}</small></span>
            </button>
            <button type="button" className="project-more" aria-label={`${project.name}更多操作`} aria-expanded={menuId===project.id} onClick={event=>{event.stopPropagation();setMenuId(menuId===project.id?null:project.id)}}><MoreHorizontal/></button>
            {menuId===project.id&&<div className="project-card-menu" onClick={event=>event.stopPropagation()}>
              <button type="button" onClick={()=>{setDraftName(project.name);setRenamingId(project.id);setMenuId(null)}}><Pencil/>重命名</button>
              <button type="button" className="danger" onClick={()=>{setProjects(items=>items.filter(item=>item.id!==project.id));setMenuId(null)}}><Trash2/>删除</button>
            </div>}
          </article>)}
        </div>
      </div>:isAssets?<div className="product-area-content product-area-v2 asset-workbench">
        <header className="area-header"><div><h1>资产库</h1><p>管理团队可复用的代码组件、确认状态和项目来源</p></div><span className="asset-header-count">{componentAssets.length} 个组件</span></header>
        <div className="asset-toolbar">
          <label><Search/><input value={assetQuery} onChange={event=>setAssetQuery(event.target.value)} placeholder="搜索组件、用途或来源项目"/>{assetQuery&&<button type="button" aria-label="清空搜索" onClick={()=>setAssetQuery('')}><X/></button>}</label>
          <div className="asset-filters">{assetFilters.map(filter=><button type="button" className={assetFilter===filter?'active':''} onClick={()=>setAssetFilter(filter)} key={filter}>{filter}<em>{filter==='全部'?componentAssets.length:componentAssets.filter(item=>item.status===filter).length}</em></button>)}</div>
        </div>
        <div className={'asset-workspace '+(selectedAsset?'has-detail':'')}>
          <section className="asset-library-grid">
            {visibleAssets.map(item=><button type="button" className={'asset-library-card '+(selectedAssetId===item.id?'selected':'')} onClick={()=>setSelectedAssetId(item.id)} key={item.id}>
              <span className="asset-preview-wrap"><ComponentPreview kind={item.kind}/><em className={'asset-status '+item.status}>{item.status}</em></span>
              <span className="asset-card-copy"><b>{item.name}</b><small>{item.project} · {item.group}</small><span><History/>{item.updated}<i>{item.version}</i></span></span>
            </button>)}
            {visibleAssets.length===0&&<div className="asset-empty"><Search/><b>没有找到组件</b><small>调整搜索词或筛选状态后再试</small></div>}
          </section>
          {selectedAsset&&<aside className="asset-detail-panel">
            <header><span><small>组件详情</small><b>{selectedAsset.name}</b></span><button type="button" aria-label="关闭组件详情" onClick={()=>setSelectedAssetId(null)}><X/></button></header>
            <div className="asset-detail-preview"><ComponentPreview kind={selectedAsset.kind}/></div>
            <p>{selectedAsset.description}</p>
            <dl><div><dt>来源项目</dt><dd>{selectedAsset.project}</dd></div><div><dt>组件分类</dt><dd>{selectedAsset.group}</dd></div><div><dt>当前版本</dt><dd>{selectedAsset.version}</dd></div><div><dt>项目引用</dt><dd>{selectedAsset.uses} 次</dd></div><div><dt>最近更新</dt><dd>{selectedAsset.updated}</dd></div></dl>
            <section className="asset-status-control"><b>资产状态</b><small>状态决定组件是否能被项目和 AI 调用</small><div>{(['待确认','项目组件','核心组件','已停用'] as AssetStatus[]).map(status=><button type="button" className={selectedAsset.status===status?'active':''} onClick={()=>updateAssetStatus(selectedAsset.id,status)} key={status}>{selectedAsset.status===status&&<Check/>}{status}</button>)}</div></section>
          </aside>}
        </div>
      </div>:<PaperLineExperts tab={tab} onTab={setTab} onAdd={()=>setAddOpen(true)} designExperts={designExperts} skillExperts={skillExperts} connectors={connectors} onToggleConnector={id=>setConnectors(items=>items.map(item=>item.id===id?{...item,connected:!item.connected}:item))} myComponents={myComponents} managing={managingComponents} onManage={()=>setManagingComponents(true)} onCancelManage={()=>setManagingComponents(false)} onDeleteComponent={id=>{setMyComponents(items=>items.filter(item=>item.id!==id));setManagingComponents(false)}}/>}
    </main>
    {addOpen&&<SkillUploadModal onClose={()=>setAddOpen(false)} onAdd={addSkillComponent}/>}
  </div>;
}

type SkillUploadTab='file'|'github'|'npx';
const uploadedSkillDescription="Guidance for distinctive, intentional visual design when building new UI or reshaping an existing one. Helps with aesthetic direction, typography, and making choices that don't read as templated defaults.";
function SkillUploadIcon({kind}:{kind:SkillUploadTab}){if(kind==='file')return <Upload/>;if(kind==='github')return <GitBranch/>;return <Terminal/>}
function SkillUploadModal({onClose,onAdd}:{onClose:()=>void;onAdd:(name:string,description:string)=>void}){
  const [activeTab,setActiveTab]=useState<SkillUploadTab>('file');
  const [source,setSource]=useState('');
  const [uploaded,setUploaded]=useState(false);
  const [skillName,setSkillName]=useState('frontend-design');
  const fileRef=useRef<HTMLInputElement>(null);
  const selectTab=(next:SkillUploadTab)=>{setActiveTab(next);setSource('');setUploaded(false)};
  const acceptFile=(file?:File)=>{if(!file)return;const clean=file.name.replace(/\.zip$/i,'').replace(/\.md$/i,'');setSkillName(clean.toLowerCase()==='skill'||!clean?'frontend-design':clean);setUploaded(true)};
  const installSource=()=>{if(!source.trim())return;const segments=source.trim().replace(/\/$/,'').split('/');setSkillName((segments[segments.length-1]||'frontend-design').replace(/\.md$/i,'')||'frontend-design');setActiveTab('file');setUploaded(true)};
  return <div className="paper-skill-layer" onPointerDown={event=>{if(event.target===event.currentTarget)onClose()}}><section className={'paper-skill-modal '+(uploaded?'uploaded':'')}>
    <header><h2>上传自定义 skill</h2><button type="button" aria-label="关闭" onClick={onClose}><X/></button></header>
    <div className="paper-skill-content"><div className="paper-skill-tabs" role="tablist">{([['file','文件'],['github','GitHub'],['npx','npx']] as [SkillUploadTab,string][]).map(([kind,label])=><button type="button" role="tab" aria-selected={activeTab===kind} className={activeTab===kind?'active':''} onClick={()=>selectTab(kind)} key={kind}><SkillUploadIcon kind={kind}/>{label}</button>)}</div>
      {activeTab==='file'?<><input ref={fileRef} className="paper-skill-file-input" type="file" accept=".md,.zip,text/markdown,application/zip" onChange={event=>acceptFile(event.target.files?.[0])}/><button type="button" className="paper-skill-drop" onClick={()=>fileRef.current?.click()} onDragOver={event=>event.preventDefault()} onDrop={event=>{event.preventDefault();acceptFile(event.dataTransfer.files?.[0])}}><Upload/><b>选择 skill 文件</b><small>支持 SKILL.md，或包含 SKILL.md 的 zip 包。</small></button>{uploaded&&<div className="paper-skill-validation"><div className="paper-skill-file"><FileText/><span><b>{skillName}</b><small>SKILL.md</small><p>{uploadedSkillDescription}</p></span></div><div className="paper-skill-valid"><CircleCheck/><span>校验通过，可以启用该 skill。</span></div><div className="paper-skill-warning">This skill mentions commands, network access, or credentials. Existing permissions still apply.</div><footer><button type="button" onClick={()=>onAdd(skillName,uploadedSkillDescription)}>添加 skill</button></footer></div>}</>:<div className="paper-skill-source"><input autoFocus value={source} onChange={event=>setSource(event.target.value)} placeholder={activeTab==='github'?'GitHub 仓库、目录或 SKILL.md 链接':'npx skills add owner/repo 或 npx -y @scope/skill-package'} onKeyDown={event=>{if(event.key==='Enter')installSource()}}/><button type="button" disabled={!source.trim()} onClick={installSource}>安装 skill</button></div>}
    </div>
  </section></div>;
}

function ProductAreaPageV2({page,onNavigate}:{page:Exclude<AppPage,'home'|'project'>;onNavigate:(page:AppPage)=>void}){
  const [collapsed,setCollapsed]=useState(false),[detail,setDetail]=useState<string|null>(null),[hubTab,setHubTab]=useState(page==='connectors'?'connectors':'skills'),[memberMenu,setMemberMenu]=useState<string|null>(null);
  const [members,setMembers]=useState([
    {name:'Leo',role:'产品设计师',permission:'可管理'},
    {name:'Lily',role:'产品经理',permission:'可编辑'},
    {name:'雅木茶',role:'前端工程师',permission:'可查看'}
  ]);
  useEffect(()=>{if(page==='connectors'||page==='skills')setHubTab(page)},[page]);
  useEffect(()=>{const close=()=>setMemberMenu(null);document.addEventListener('pointerdown',close);return()=>document.removeEventListener('pointerdown',close)},[]);
  const projects=[['速学慧','Figma · 已连接','18 个页面'],['想象力智能中高考','GitHub · 已连接','12 个页面'],['代理商小程序','Figma · 待同步','9 个页面'],['品牌活动中心','GitHub · 已连接','7 个页面']];
  const specs=[['Imagine Design','速学慧','v1.3 · 团队核心规范','#657a6d'],['商城后台规范','代理商小程序','v2.1 · 已发布','#586b87'],['移动端轻量规范','智能中高考','v0.9 · 待确认','#8a7768']];
  const title=page==='connectors'||page==='skills'?'技能与连接':areaMeta[page].title;
  return <div className="home-page product-area-page"><HomeSidebar goProject={()=>onNavigate('project')} goHome={()=>onNavigate('home')} onNavigate={onNavigate} collapsed={collapsed} active={page}/><main className="home-main"><Header crumb={title} onToggleSidebar={()=>setCollapsed(v=>!v)}/><div className="product-area-content product-area-v2"><header><div><h1>{title}</h1><p>{page==='projects'?'管理已导入的设计项目和代码项目':page==='specs'?'查看并管理团队确认过的核心设计规范':page==='team'?'管理成员和项目访问权限':page==='assets'?'浏览团队可复用的代码组件':'让专家能力与数据连接自然进入工作流'}</p></div>{page==='projects'&&<button className="area-primary"><Import/>导入项目</button>}{page==='team'&&<button className="area-primary"><UserPlus/>邀请成员</button>}</header>
  {page==='projects'?<div className="area-project-grid project-card-grid">{projects.map(([name,source,count])=><button onClick={()=>onNavigate('project')} key={name}><span><FolderKanban/></span><div><b>{name}</b><small>{source}</small></div><em>{count}</em><ChevronRight/></button>)}</div>
  :page==='assets'?<><div className="area-toolbar"><label><Search/><input placeholder="搜索组件、用途或来源项目"/></label>{['全部组件','项目组件','核心组件','待确认'].map((x,i)=><button className={i===0?'active':''} key={x}>{x}</button>)}</div><div className="area-component-grid">{workspaceComponents.map(([name,kind,group])=><article key={name}><ComponentPreview kind={kind}/><footer><span><b>{name}</b><small>速学慧 · {group}</small></span><button><MoreHorizontal/></button></footer></article>)}</div></>
  :page==='specs'?detail?<section className="spec-detail"><header><button onClick={()=>setDetail(null)}><ArrowLeft/></button><div><h2>{detail}</h2><small>速学慧 · v1.3 · 已锁定</small></div><button className="spec-export"><Download/>导出 DESIGN.md</button></header><div className="spec-board"><article className="palette-card"><b>核心色板</b><div>{['#1f2a24','#657a6d','#dfe6e1','#f7f5ef'].map(c=><i key={c} style={{background:c}}><span>{c}</span></i>)}</div></article><article className="type-card"><b>字体层级</b><h3>把想象变成团队生产力</h3><p>标题 28 / 正文 14 / 辅助 12</p></article><article className="radius-card"><b>形状与间距</b><div><i/><i/><i/></div><p>8px 网格 · 10px 圆角 · 轻量描边</p></article><article className="control-card"><b>基础控件</b><button>主要按钮</button><button>次要按钮</button><label><input placeholder="输入内容"/></label></article></div></section>:<div className="spec-master"><div className="spec-master-head"><b>项目设计规范</b><span>选择项目查看可视化规范和 DESIGN.md</span></div><div className="spec-card-grid">{specs.map(([name,project,version,color])=><button key={name} onClick={()=>setDetail(name)}><div className="spec-card-preview" style={{'--spec-color':color} as React.CSSProperties}><span>Aa</span><i/><em>Button</em></div><b>{name}</b><small>{project}</small><p>{version}</p><ChevronRight/></button>)}</div></div>
  :(page==='skills'||page==='connectors')?<><div className="hub-tabs"><button className={hubTab==='skills'?'active':''} onClick={()=>setHubTab('skills')}><WandSparkles/>专家技能</button><button className={hubTab==='connectors'?'active':''} onClick={()=>setHubTab('connectors')}><Link2/>连接器</button></div>{hubTab==='skills'?<div className="expert-grid skill-hub-grid">{[['页面生成专家','按现有规范和组件生成新页面'],['组件识别专家','从导入页面中识别可复用组件'],['规范检查专家','检查页面偏离并给出修改建议'],['交付整理专家','整理 UI 代码、依赖和使用说明']].map(([name,desc],i)=><article key={name}><span>{i===0?<WandSparkles/>:i===1?<Component/>:i===2?<ShieldCheck/>:<Archive/>}</span><b>{name}</b><p>{desc}</p><button>查看能力<ChevronRight/></button></article>)}</div>:<div className="connector-list">{[['Figma','同步设计页面与组件来源','已连接'],['GitHub','同步前端仓库与运行项目','已连接'],['亿方云','存放团队资产、版本与交付包','未连接']].map(([name,desc,status])=><article key={name}><i>{name[0]}</i><span><b>{name}</b><small>{desc}</small></span><em className={status==='已连接'?'connected':''}>{status}</em><button>{status==='已连接'?'管理':'连接'}<ChevronRight/></button></article>)}</div>}</>
  :<div className="team-member-page"><div className="team-table-head"><span>成员</span><span>工作角色</span><span>权限</span></div>{members.map(member=><div className="team-member-row" key={member.name}><span><Avatar/><b>{member.name}</b></span><span>{member.role}</span><div className="member-permission-control" onPointerDown={event=>event.stopPropagation()}><button onClick={()=>setMemberMenu(memberMenu===member.name?null:member.name)}>{member.permission}<ChevronDown/></button>{memberMenu===member.name&&<div className="member-permission-menu">{['可管理','可编辑','可查看'].map(permission=><button key={permission} onClick={()=>{setMembers(current=>current.map(item=>item.name===member.name?{...item,permission}:item));setMemberMenu(null)}}>{permission}</button>)}<i/><button className="danger" onClick={()=>{setMembers(current=>current.filter(item=>item.name!==member.name));setMemberMenu(null)}}>移出团队</button></div>}</div></div>)}</div>}
  </div></main></div>
}
function UnifiedApp(){
  const [page,setPage]=useState<AppPage>('home')
  useEffect(()=>{
    const navigate=(event:MouseEvent)=>{
      const title=(event.target as HTMLElement).closest('button[title]')?.getAttribute('title')
      const map:Record<string,AppPage>={'项目':'projects','资产库':'assets','专家与连接':'specs','设计规范':'specs','技能库':'skills','连接器':'connectors','团队设置':'team'}
      if(title&&map[title])setPage(map[title])
    }
    document.addEventListener('click',navigate)
    return()=>document.removeEventListener('click',navigate)
  },[])
  if(page==='home')return <Home goProject={()=>setPage('project')}/>
  if(page==='project')return <Project goHome={()=>setPage('home')}/>
  if(page==='projects'||page==='assets'||page==='specs'||page==='skills'||page==='connectors')return <ProductAreaPageV3 page={page} onNavigate={setPage}/>
  return <ProductAreaPageV2 page={page} onNavigate={setPage}/>
}

createRoot(document.getElementById('root')!).render(<UnifiedApp/>);
